    public YourBotClass()
    {
        _httpClient = new HttpClient();
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _openAiApiToken);
        _httpClient.DefaultRequestHeaders.Accept.Add(new MediaTypeWithQualityHeaderValue("application/json"));
    }

    public async Task<string> GenerateAIResponse(string prompt)
    {
        var request = new
        {
            model = "gpt-4o-mini", // 确保使用正确的模型名称
            messages = new[]
            {
                new
                {
                    role = "user",
                    content = prompt
                }
            },
            stream = false,
            temperature = 0.7, // 可选参数，设置采样温度
            top_p = 1.0, // 可选参数，设置核采样值
            n = 1, // 可选参数，设置生成的选项数量
            max_tokens = 150, // 可选参数，设置最大生成的令牌数
            presence_penalty = 0.0, // 可选参数，设置存在惩罚
            frequency_penalty = 0.0, // 可选参数，设置频率惩罚
            logit_bias = new { } // 可选参数，设置标记偏差
        };

        var jsonRequest = JsonConvert.SerializeObject(request);
        var content = new StringContent(jsonRequest, Encoding.UTF8, "application/json");

        try
        {
            var response = await _httpClient.PostAsync("https://api.qhaigc.net/v1/chat/completions", content);
            response.EnsureSuccessStatusCode();
            var responseString = await response.Content.ReadAsStringAsync();

            // 解析响应
            var responseObject = JsonConvert.DeserializeObject<OpenAIResponse>(responseString);
            if (responseObject != null && responseObject.choices != null && responseObject.choices.Length > 0)
            {
                return responseObject.choices[0].message.content;
            }
            else
            {
                return "AI助手没有生成有效的回复。";
            }
        }
        catch (Exception ex)
        {
            return "调用AI助手时发生错误: " + ex.Message;
        }
    }

    // 定义OpenAI API响应的结构
    private class OpenAIResponse
    {
        public string id { get; set; }
        public string @object { get; set; }
        public long created { get; set; }
        public Choice[] choices { get; set; }
        public Usage usage { get; set; }
    }

    private class Choice
    {
        public int index { get; set; }
        public Message message { get; set; }
        public string finish_reason { get; set; }
    }

    private class Message
    {
        public string role { get; set; }
        public string content { get; set; }
    }

    private class Usage
    {
        public int prompt_tokens { get; set; }
        public int completion_tokens { get; set; }
        public int total_tokens { get; set; }
    }
